L000883	\section{Numerical evaluation of the velocity structure function}
L000884	To numerically calculate the velocity structure function
L000885	\begin{equation}
L000886	S_p \left( r \right)
L000887	\coloneqq
L000888	\frac{1}{2 \pi L^2}
L000889	\int_{0}^{2 \pi}
L000890	\int_{0}^{L}
L000891	\int_{0}^{L}
L000892	\left\vert
L000893	\left\lbrack
L000894	\boldsymbol{u}_i \left( \boldsymbol{R} + \boldsymbol{r} \right)
L000895	-
L000896	\boldsymbol{u}_i \left( \boldsymbol{R} \right)
L000897	\right\rbrack
L000898	\cdot
L000899	\boldsymbol{e}_r
L000900	\right\vert^p
L000901	\;
L000902	d R_x \;
L000903	d R_y \;
L000904	d \varphi
L000905	,
L000906	\label{supp:eq:Sp}
L000907	\end{equation}
L000908	where $\boldsymbol{e}_r \coloneqq \boldsymbol{r} / r = \left( \cos \varphi, \sin \varphi \right)$ is the unit vector along $\boldsymbol{r}$ \cite{Ciliberto1994,Frisch1995}, we compute the velocity increments using the discrete Fourier transform, implemented via the Julia package \texttt{FFTW.jl}.
L000909	Let $\nu_j \coloneqq \left( j - 1 \right) L_{\nu} / N_{\nu}$ for $1 \le j \le N_{\nu}$ with $\nu = x, y$. The weighted superfluid velocity $\boldsymbol{u} \left( x_j, y_l\right)$ can then be written as
L000910	\begin{equation}
L000911	\boldsymbol{u} \left( x_j, y_l \right)
L000912	=
L000913	\frac{1}{N_x N_y}
L000914	\sum_{n_x = 1}^{N_x}
L000915	\sum_{n_y = 1}^{N_y}
L000916	\boldsymbol{\tilde{u}}\left( n_x - 1, n_y - 1 \right)
L000917	e^{2 \pi i \left( n_x - 1 \right) \left( j - 1 \right) / N_x}
L000918	e^{2 \pi i \left( n_y - 1 \right) \left( l - 1 \right) / N_y}
L000919	,
L000920	\end{equation}
L000921	where we used $\boldsymbol{k} / 2 \pi = \left( \left( n_x - 1 \right) / L_x, \left( n_y - 1 \right) / L_y \right)$ in the discrete Fourier space.
L000922	Since $\boldsymbol{u} \left( x_j, y_l \right)$ is real, its derivatives must also be real.
L000923	Using the identity $\exp \left( 2 \pi i \left( n_{\nu} - 1 \right) \left( j - 1 \right) / N_{\nu} \right) = \exp \left( 2 \pi i \left( n_{\nu} - 1 - N_{\nu} \right) \left( j - 1 \right) / N_{\nu} \right)$ for any integers $1 \le n_{\nu} \le N_{\nu}$ and $1 \le j \le N_{\nu}$, in order to make $\boldsymbol{u}_i \left( x_j, y_l \right)$ real, one should use the following expression:
L000924	\begin{equation}
L000925	\boldsymbol{u}_i \left( x_j, y_l \right)
L000926	=
L000927	\frac{1}{N_x N_y}
L000928	\sum_{n_x = 1}^{N_x}
L000929	\sum_{n_y = 1}^{N_y}
L000930	\frac{
L000931	\boldsymbol{k} \left( n_x, n_y \right)
L000932	}{
L000933	k^2 \left( n_x, n_y \right)
L000934	}
L000935	\times
L000936	\left\lbrack
L000937	\boldsymbol{\tilde{u}}\left( n_x - 1, n_y - 1 \right)
L000938	\times
L000939	\boldsymbol{k} \left( n_x, n_y \right)
L000940	\right\rbrack
L000941	e^{2 \pi i \left( n_x - 1 \right) \left( j - 1 \right) / N_x}
L000942	e^{2 \pi i \left( n_y - 1 \right) \left( l - 1 \right) / N_y}
L000943	,
L000944	\label{eq:app:u_i_discrete_space}
L000945	\end{equation}
L000946	with $\boldsymbol{k} \left( n_x, n_y \right) \coloneqq \sum_{\nu = x, y} k_{\nu} \left( n_x, n_y \right) \boldsymbol{e}_{\nu} $ and
L000947	\begin{equation}
L000948	k_{\nu} \left( n_x, n_y \right)
L000949	\coloneqq
L000950	\left\{
L000951	\begin{array}{cc}
L000952	2 \pi i \left( n_{\nu} - 1 \right) / L_{\nu}
L000953	,
L000954	&
L000955	\textrm{ if \; $1 \le n_{\nu} \le \left\lbrack N_{\nu} / 2 \right\rbrack_r + 1$,}
L000956	\\
L000957	\\
L000958	2 \pi i \left( n_{\nu} - 1 - N_{\nu} \right) / L_{\nu}
L000959	,
L000960	&
L000961	\textrm{ otherwise,}
L000962	\end{array}
L000963	\right.
L000964	\end{equation}
L000965	where $\left\lbrack x \right\rbrack_r$ is the greatest integer less than or equal to $x$, so that $- 2 \pi i \left\lbrack N_{\nu} / 2 \right\rbrack_r / L_{\nu} \le k_{\nu} \left( n_x, n_y \right) \le 2 \pi i \left\lbrack N_{\nu} / 2 \right\rbrack_r / L_{\nu}$.
L000966	
L000967	Note that, for any function $f \left( x, y \right)$ in the periodic system $f \left( x + L_x, y \right) = f \left( x, y + L_y \right) = f \left( x, y \right)$,
L000968	\begin{equation}
L000969	\frac{1}{L_x L_y}
L000970	\int_0^{L_x}
L000971	\int_0^{L_y}
L000972	f \left( x, y \right) \;
L000973	d y \;
L000974	d x
L000975	=
L000976	\frac{1}{N_x N_y}
L000977	\sum_{j = 1}^{N_x}
L000978	\sum_{l = 1}^{N_y}
L000979	f \left( x_j, y_l \right)
L000980	.
L000981	\label{eq:app:spatial_numerical_integration}
L000982	\end{equation}
L000983	After numerically calculating $\boldsymbol{u}_i \left( x_j, y_l \right)$ via Eq. \eqref{eq:app:u_i_discrete_space},
L000984	we calculate
L000985	$
L000986	\Delta \boldsymbol{u}_i \left( \boldsymbol{R}, \boldsymbol{r} \right)
L000987	\coloneqq
L000988	\boldsymbol{u}_i \left( \boldsymbol{R} + \boldsymbol{r} \right)
L000989	-
L000990	\boldsymbol{u}_i \left( \boldsymbol{R} \right)
L000991	$ and then calculate $S_p \left( r \right)$ numerically as
L000992	\begin{equation}
L000993	S_p \left( r \right)
L000994	=
L000995	\frac{1}{L^2}
L000996	\int_{0}^{L}
L000997	\int_{0}^{L}
L000998	\left\lbrack
L000999	\frac{1}{2 \pi}
L001000	\int_0^{2 \pi}
L001001	\left\vert
L001002	\Delta \boldsymbol{u}_i \left( \boldsymbol{R}, \boldsymbol{r} \right)
L001003	\cdot
L001004	\boldsymbol{e}_r
L001005	\right\vert^p \;
L001006	d \varphi
L001007	\right\rbrack \;
L001008	d R_x \;
L001009	d R_y
L001010	=
L001011	\frac{1}{N^2_x}
L001012	\sum_{j, l = 1}^{N_x}
L001013	\left\lbrack
L001014	\frac{1}{2 \pi}
L001015	\int_{0}^{2 \pi}
L001016	\left\vert
L001017	\Delta \boldsymbol{u}_i \left( X_j, Y_l, \boldsymbol{r} \right)
L001018	\cdot
L001019	\boldsymbol{e}_r
L001020	\right\vert^p \;
L001021	d \varphi
L001022	\right\rbrack
L001023	,
L001024	\end{equation}
L001025	with $X_j \coloneqq \left( j - 1 \right) L / N_x$ and $Y_l \coloneqq \left( l - 1 \right) L / N_x$.
